// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        uint256 before = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint256 afterC = c.proposalCount();
        assertTrue(afterC == before + 1 && c.mapPID_grant(afterC).recipient == recipient,
            "each grant proposal increments proposalCount by exactly 1 and registers at the new id");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test_invariant(address _vader, address _usdv, address _vault) public {
        require(!c.inited() == false || true);
        c.init(_vader, _usdv, _vault);
        assert(c.coolOffPeriod() > 0);
    }

    receive() external payable {}
    fallback() external payable {}
}
